import 'dart:typed_data';
import 'package:audioplayers/audioplayers.dart';
import 'package:flutter_tts/flutter_tts.dart';
import 'api_service.dart';

/// Speaks text aloud.
///
/// Urdu (and English) audio is generated by the backend (/api/tts) and played
/// with audioplayers, so it sounds right on every phone - no Urdu voice needs
/// to be installed. If the backend can't be reached, we fall back to the
/// phone's own flutter_tts voice so the button never just does nothing.
class TtsService {
  final AudioPlayer _player = AudioPlayer();
  final FlutterTts _fallback = FlutterTts();
  final ApiService _api = ApiService();
  final Map<String, Uint8List> _cache = {}; // replaying doesn't re-download
  void Function()? _onDone;

  TtsService() {
    _player.onPlayerComplete.listen((_) => _onDone?.call());
    _fallback.setCompletionHandler(() => _onDone?.call());
  }

  /// Urdu now comes from the server, so it is always "available".
  Future<bool> isUrduAvailable() async => true;

  Future<void> speak(String text, {required String lang}) async {
    try {
      final key = '$lang|$text';
      final bytes =
          _cache[key] ??= await _api.synthesizeSpeech(text, lang: lang);
      await _player.stop();
      await _player.play(BytesSource(bytes));
    } catch (_) {
      await _speakOnDevice(text, lang);
    }
  }

  Future<void> _speakOnDevice(String text, String lang) async {
    try {
      var locale = 'en-US';
      if (lang == 'ur') {
        final langs = ((await _fallback.getLanguages) as List).cast<String>();
        if (langs.any((l) => l.toLowerCase().startsWith('ur'))) {
          locale = 'ur-PK';
        }
      }
      await _fallback.setLanguage(locale);
      await _fallback.setSpeechRate(0.45);
      await _fallback.speak(text);
    } catch (_) {
      _onDone?.call(); // reset the play button
    }
  }

  Future<void> stop() async {
    await _player.stop();
    await _fallback.stop();
  }

  Future<void> dispose() async {
    await stop();
    await _player.dispose();
  }

  void onCompletion(void Function() cb) => _onDone = cb;
}
